import {seed,validate,stages,match,csv} from './model.js';
const $=s=>document.querySelector(s), key='talent-bridge-v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('zh-TW').format(n);
const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
let state,readError=false;try{const raw=localStorage.getItem(key);state=raw?validate(JSON.parse(raw)):seed();}catch{state=seed();readError=true;}
let page='dashboard',query='',filter='',editing=null;
const views={dashboard:['◫','工作總覽'],talents:['♧','人才資料庫'],jobs:['▣','企業與職缺'],referrals:['⇄','推薦案件'],pipeline:['▥','招募看板'],reports:['◴','分析報表']};
const findT=id=>state.talents.find(x=>x.id===id),findJ=id=>state.jobs.find(x=>x.id===id);
const badge=s=>`<span class="badge ${['企業面試','初步評估'].includes(s)?'blue':['錄取洽談','暫停'].includes(s)?'gold':['未錄取','暫不考慮','已結案'].includes(s)?'gray':''}">${esc(s)}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function persist(next,message){try{validate(next);next.activities.unshift({text:message,time:new Date().toISOString()});next.activities=next.activities.slice(0,100);localStorage.setItem(key,JSON.stringify(next));state=next;render();toast(message);return true;}catch(e){toast('儲存失敗：'+e.message);return false;}}
function heading(title,sub,action){return `<div class="heading"><div><span class="eyebrow">YOUR TALENT CONNECTIONS</span><h1>${title}</h1><p>${sub}</p></div>${action?`<button class="primary" data-new="${action}">＋ 新增${{talents:'人才',jobs:'職缺',referrals:'推薦'}[action]}</button>`:''}</div>`;}
function stats(){const active=state.referrals.filter(r=>!['已到職','未錄取'].includes(r.stage)).length,hired=state.referrals.filter(r=>r.stage==='已到職');return `<div class="stats">${[['人才資料庫',state.talents.length,'位人才，等待下一個機會'],['招募中職缺',state.jobs.filter(j=>j.status==='招募中').length,'個機會，連結理想夥伴'],['進行中推薦',active,'筆案件，持續推進中'],['成功到職',hired.length,`介紹費合計 NT$ ${money(hired.reduce((s,r)=>s+r.fee,0))}`]].map(([a,b,c])=>`<div class="stat"><label>${a} <span style="float:right">↗</span></label><strong>${b}<span style="font-size:12px;font-weight:400;color:#9da79b"> / ${a==='人才資料庫'?'人':'筆'}</span></strong><small>${c}</small></div>`).join('')}</div>`;}
function dashboard(){const upcoming=state.referrals.filter(r=>!['已到職','未錄取'].includes(r.stage)).sort((a,b)=>a.date.localeCompare(b.date));return heading('讓好人才，遇見對的機會。','掌握每一次連結，讓下一個理想配對發生。','referrals')+`<div class="hero"><div><span class="eyebrow">MAKE THE RIGHT CONNECTION</span><h2>好的介紹，從理解人才開始。</h2><p>從第一通聯繫到正式到職，把每個關鍵時刻串在一起。<br>今天也為人才與企業，搭起一座新的橋梁。</p></div><div class="hero-art" aria-hidden="true">◯↗◯</div></div>`+stats()+`<div class="grid"><div class="panel"><div class="panel-head"><h2>招募流程概況</h2><a href="#pipeline">查看招募看板 ↗</a></div><div class="funnel">${stages.slice(0,5).map(s=>{const n=state.referrals.filter(r=>r.stage===s).length;return `<div class="bar-group"><strong>${n}</strong><div class="bar" style="height:${Math.max(6,n/Math.max(1,...stages.map(s=>state.referrals.filter(r=>r.stage===s).length))*100)}px"></div><small>${s}</small></div>`;}).join('')}</div><p class="footnote">目前各階段案件數 · 已到職及未錄取案件為結案狀態。</p></div><div class="panel"><div class="panel-head"><h2>接下來的跟進</h2><a href="#referrals">所有案件 ↗</a></div>${upcoming.slice(0,3).map(r=>`<div class="row"><span class="avatar">${esc(findT(r.talentId).name[0])}</span><div class="grow"><strong>${esc(findT(r.talentId).name)}</strong><small>${esc(findJ(r.jobId).company)} · ${r.date}</small></div>${badge(r.stage)}</div>`).join('')||'<div class="empty">目前沒有待跟進案件</div>'}</div></div><div class="panel section-gap"><div class="panel-head"><h2>最近推薦案件</h2><a href="#referrals">查看全部 ↗</a></div>${referralTable(state.referrals.slice(0,4))}</div>`;}
function toolbar(options){return `<div class="toolbar"><input id="search" aria-label="搜尋" placeholder="搜尋姓名、公司、職稱或技能…" value="${esc(query)}"><select id="filter" aria-label="狀態篩選"><option value="">所有狀態</option>${options.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><button id="export">↓ 匯出 CSV</button></div>`;}
function filtered(rows){const q=query.toLowerCase().trim();return rows.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!filter||(x.status||x.stage)===filter));}
function talentTable(rows){return `<div class="table-wrap"><table><thead><tr><th>人才 / 職稱</th><th>技能</th><th>地點 / 年資</th><th>期望年薪</th><th>求職狀態</th><th>操作</th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.name)}</strong><small>${esc(t.title)}</small></td><td><div class="tags">${t.skills.split(',').map(s=>`<span class="tag">${esc(s.trim())}</span>`).join('')}</div></td><td>${esc(t.location)}<small>${t.years} 年經驗</small></td><td>${t.salary} 萬</td><td>${badge(t.status)}</td><td><button data-edit="talents:${esc(t.id)}">編輯</button> <button data-match="${esc(t.id)}">配對</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">沒有符合條件的人才，試試調整搜尋。</div>'}</div>`;}
function referralTable(rows){return `<div class="table-wrap"><table><thead><tr><th>推薦人才</th><th>企業 / 職缺</th><th>推薦人</th><th>進度</th><th>下次跟進</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(findT(r.talentId).name)}</strong><small>${esc(findT(r.talentId).title)}</small></td><td>${esc(findJ(r.jobId).company)}<small>${esc(findJ(r.jobId).title)}</small></td><td>${esc(r.referrer)}</td><td>${badge(r.stage)}</td><td class="${r.date<today()&&!['已到職','未錄取'].includes(r.stage)?'danger':''}">${r.date}</td><td><button data-edit="referrals:${esc(r.id)}">管理</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">尚無符合條件的推薦案件</div>'}</div>`;}
function jobs(){const rows=filtered(state.jobs);return heading('企業與職缺','集中管理企業需求，找到下一個值得介紹的機會。','jobs')+toolbar(['招募中','暫停','已結案'])+`<div class="cards">${rows.map(j=>`<article class="panel job"><div style="display:flex;justify-content:space-between"><span class="avatar">${esc(j.company[0])}</span>${badge(j.status)}</div><h2>${esc(j.title)}</h2><p>${esc(j.company)} · ${esc(j.location)}</p><div class="tags">${j.skills.split(',').map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><p>年薪上限 ${j.salary} 萬 · 需求 ${j.slots} 人</p><p>${esc(j.notes)||'尚無職缺備註'}</p><div class="job-bottom"><small>${state.referrals.filter(r=>r.jobId===j.id).length} 位推薦人才</small><button data-edit="jobs:${esc(j.id)}">管理職缺 ↗</button></div></article>`).join('')}</div>${rows.length?'':'<div class="empty">目前沒有符合條件的職缺</div>'}`;}
function pipeline(){return heading('每一個階段，都看得見。','透過案件下方選單調整進度，所有變更即時儲存在本機。','referrals')+`<div class="board">${stages.map(s=>`<section class="column"><h3>${s}<span>${state.referrals.filter(r=>r.stage===s).length}</span></h3>${state.referrals.filter(r=>r.stage===s).map(r=>`<article class="candidate"><span class="avatar">${esc(findT(r.talentId).name[0])}</span><h4>${esc(findT(r.talentId).name)}</h4><p>${esc(findJ(r.jobId).title)}</p><p>${esc(findJ(r.jobId).company)} · ${esc(r.referrer)}</p><p>跟進 ${r.date}</p><select aria-label="${esc(findT(r.talentId).name)}的案件階段" data-stage="${esc(r.id)}">${stages.map(x=>`<option ${x===s?'selected':''}>${x}</option>`).join('')}</select></article>`).join('')||'<div class="empty">尚無案件</div>'}</section>`).join('')}</div>`;}
function reports(){const total=state.referrals.length,hired=state.referrals.filter(r=>r.stage==='已到職');const sources=[...new Set(state.referrals.map(r=>r.referrer))];return heading('用數據，看見連結的價值。','依目前所有案件計算，非歷史期間或同批人才轉換率。')+stats()+`<div class="grid"><div class="panel"><div class="panel-head"><h2>推薦來源表現</h2><span class="eyebrow">REFERRAL SOURCES</span></div>${sources.map(s=>{const n=state.referrals.filter(r=>r.referrer===s).length;return `<div class="report-row"><span>${esc(s)}</span><div class="progress"><i style="width:${n/Math.max(1,total)*100}%"></i></div><span>${n} 筆</span></div>`;}).join('')||'<div class="empty">尚無推薦資料</div>'}<p class="footnote">長條表示該推薦人案件數占所有推薦案件的比例。</p></div><div class="panel"><div class="panel-head"><h2>到職與介紹費</h2></div><div class="stat"><label>整體到職占比</label><strong>${total?Math.round(hired.length/total*100):0}%</strong><small>已到職案件 ÷ 所有案件</small></div><div class="row"><div class="grow">已到職案件介紹費<small>僅為約定金額，未追蹤請款或收款</small></div><strong>NT$ ${money(hired.reduce((s,r)=>s+r.fee,0))}</strong></div></div></div><div class="panel section-gap"><div class="panel-head"><h2>最近操作紀錄</h2></div>${state.activities.slice(0,12).map(a=>`<div class="row"><div class="grow">${esc(a.text)}</div><small>${esc(new Date(a.time).toLocaleString('zh-TW'))}</small></div>`).join('')||'<p class="empty">開始管理人才後，操作紀錄會出現在這裡。</p>'}</div>`;}
function render(){const h=location.hash.slice(1);page=views[h]?h:'dashboard';$('nav').innerHTML=Object.entries(views).map(([k,[icon,label]])=>`<a href="#${k}" class="${page===k?'active':''}"><b>${icon}</b>${label}${k==='talents'?`<em>${state.talents.length}</em>`:''}</a>`).join('');$('#breadcrumb').textContent='工作空間 / '+views[page][1];$('#today').textContent=new Date().toLocaleDateString('zh-TW',{year:'numeric',month:'long',day:'numeric'});$('#content').innerHTML=page==='dashboard'?dashboard():page==='talents'?heading('每一位人才，都有無限可能。','建立有溫度的人才關係，讓專業與機會精準相遇。','talents')+toolbar(['開放機會','積極求職','暫不考慮'])+`<div class="panel">${talentTable(filtered(state.talents))}</div>`:page==='jobs'?jobs():page==='referrals'?heading('把每一次推薦，變成可能。','追蹤推薦來源、面試進度與介紹費，讓合作更清楚。','referrals')+toolbar(stages)+`<div class="panel">${referralTable(filtered(state.referrals.map(r=>({...r,search:findT(r.talentId).name+' '+findJ(r.jobId).title+' '+findJ(r.jobId).company}))))}</div>`:page==='pipeline'?pipeline():reports();}
const fields={talents:[['name','姓名'],['title','專業職稱'],['email','電子郵件','email'],['location','所在地'],['skills','技能（逗號分隔）'],['years','工作年資','number'],['salary','期望年薪（萬元）','number'],['status','求職狀態',['開放機會','積極求職','暫不考慮']],['notes','人才備註','textarea']],jobs:[['title','職缺名稱'],['company','企業名稱'],['location','工作地點'],['skills','必要技能（逗號分隔）'],['salary','年薪上限（萬元）','number'],['slots','需求人數','number'],['status','職缺狀態',['招募中','暫停','已結案']],['notes','職缺說明','textarea']],referrals:[['talentId','推薦人才','talent'],['jobId','推薦職缺','job'],['referrer','推薦人'],['stage','目前階段',stages],['date','下次跟進日期','date'],['fee','約定介紹費（元）','number'],['notes','案件備註','textarea']]};
function openEditor(type,id,defaults={}){if(type==='referrals'&&(!state.talents.length||!state.jobs.length))return toast('請先建立人才與職缺');editing={type,id};const row=state[type].find(x=>x.id===id)||{years:0,salary:0,slots:1,fee:0,date:today(),...defaults};$('#dialog-title').textContent=(id?'編輯':'新增')+{talents:'人才資料',jobs:'企業職缺',referrals:'推薦案件'}[type];$('#form-error').textContent='';$('#fields').innerHTML=fields[type].map(([key,label,kind='text'])=>{let opts=Array.isArray(kind)?kind.map(x=>[x,x]):kind==='talent'?state.talents.map(t=>[t.id,t.name+' · '+t.title]):kind==='job'?state.jobs.map(j=>[j.id,j.company+' · '+j.title]):null;let value=row[key]??'';return `<label class="${kind==='textarea'?'wide':''}">${label}${opts?`<select name="${key}" required>${opts.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea name="${key}" maxlength="2000">${esc(value)}</textarea>`:`<input name="${key}" type="${kind}" value="${esc(value)}" required ${kind==='number'?`min="${key==='slots'?1:0}" step="${['years','slots'].includes(key)?'1':'0.1'}"`:kind==='text'?'maxlength="150"':''}>`}</label>`;}).join('');$('.dialog-actions').style.display='flex';$('#editor').showModal();}
$('#edit-form').addEventListener('submit',e=>{e.preventDefault();if(!editing)return;const {type,id}=editing;const row={id:id||crypto.randomUUID()};for(const [k,,kind] of fields[type])row[k]=kind==='number'?Number(new FormData(e.target).get(k)):String(new FormData(e.target).get(k)||'').trim();const next=structuredClone(state);if(id)next[type][next[type].findIndex(x=>x.id===id)]=row;else next[type].unshift(row);try{validate(next);if(persist(next,(id?'更新':'新增')+{talents:'人才',jobs:'職缺',referrals:'推薦案件'}[type]+'：'+(row.name||row.title||findT(row.talentId).name)))$('#editor').close();}catch(err){$('#form-error').textContent=err.message;}});
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.new)openEditor(btn.dataset.new);if(btn.dataset.edit){const [type,id]=btn.dataset.edit.split(':');openEditor(type,id);}if(btn.dataset.match){const t=findT(btn.dataset.match);editing=null;$('#dialog-title').textContent=t.name+'的技能配對';$('#form-error').textContent='';$('.dialog-actions').style.display='none';$('#fields').innerHTML=`<div class="wide"><div class="note">依職缺必要技能的完整字詞交集計算。僅提供人工評估參考，不代表錄取機率；未評估薪資、地點或其他條件。</div>${state.jobs.filter(j=>j.status==='招募中').map(j=>({j,score:match(t,j)})).sort((a,b)=>b.score-a.score).map(({j,score})=>`<div class="match-row"><strong>${esc(j.title)} · ${score}% 技能符合</strong><p>${esc(j.company)} · ${esc(j.skills)} · ${j.salary} 萬</p><button data-refer="${esc(t.id)}:${esc(j.id)}">建立推薦</button></div>`).join('')||'<p>目前沒有招募中職缺。</p>'}</div>`;$('#editor').showModal();}if(btn.dataset.refer){const [talentId,jobId]=btn.dataset.refer.split(':');$('#editor').close();openEditor('referrals',null,{talentId,jobId});}if(btn.id==='export')exportCSV();});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}if(e.target.dataset.stage){const next=structuredClone(state),r=next.referrals.find(r=>r.id===e.target.dataset.stage);r.stage=e.target.value;persist(next,'更新推薦階段：'+findT(r.talentId).name+' → '+r.stage);}});
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){let rows;if(page==='talents')rows=[['姓名','職稱','Email','地點','技能','年資','期望年薪萬元','狀態','備註'],...state.talents.map(t=>[t.name,t.title,t.email,t.location,t.skills,t.years,t.salary,t.status,t.notes])];else if(page==='jobs')rows=[['職缺','企業','地點','技能','年薪上限萬元','人數','狀態','備註'],...state.jobs.map(j=>[j.title,j.company,j.location,j.skills,j.salary,j.slots,j.status,j.notes])];else rows=[['人才','企業','職缺','推薦人','階段','跟進日期','介紹費元','備註'],...state.referrals.map(r=>[findT(r.talentId).name,findJ(r.jobId).company,findJ(r.jobId).title,r.referrer,r.stage,r.date,r.fee,r.notes])];download(csv(rows),`talent-bridge-${page}-${today()}.csv`,'text/csv;charset=utf-8');toast('已匯出此模組的全部資料（含篩選隱藏項目）');}
$('#backup').onclick=()=>download(JSON.stringify(state,null,2),`talent-bridge-backup-${today()}.json`,'application/json');$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('檔案超過 5MB');const next=validate(JSON.parse(await file.text()));if(confirm(`還原 ${next.talents.length} 位人才、${next.jobs.length} 個職缺、${next.referrals.length} 筆推薦？將取代目前資料，請先備份。`))persist(next,'從備份還原工作空間');}catch(err){toast('無法還原：'+err.message);}e.target.value='';};
window.addEventListener('hashchange',()=>{query='';filter='';render();});window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{state=validate(JSON.parse(e.newValue));render();toast('已同步其他分頁的更新');}catch{toast('其他分頁的資料格式有誤，未載入');}}});render();if(readError)toast('既有資料無法讀取，暫時顯示示範資料；請先檢查備份。');
